import pygame
import sys

# Game over screen class
class GameOverScreen:
    def __init__(self, window):
        self.window = window
        self.font = pygame.font.Font(None, 74)
        self.title = self.font.render("Game Over!", True, (255, 0, 0))
        self.play_again = self.font.render("Press SPACE to play again", True, (255, 255, 255))
        self.rect = self.title.get_rect(center=(320, 240))
        self.play_again_rect = self.play_again.get_rect(center=(320, 360))

    def draw(self):
        self.window.fill((0, 0, 0))
        self.window.blit(self.title, self.rect)
        self.window.blit(self.play_again, self.play_again_rect)

    def handle_event(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_SPACE:
                return True  # Play again
        return False

import numpy as np
import random

class SnakeGame:
    def __init__(self, width=640, height=480):
        self.width = width
        self.height = height
        self.snake = [(width // 2, height // 2)]
        self.direction = 'right'
        self.food = self.generate_food()
        self.score = 0
        self.game_over = False

    def generate_food(self):
        return (random.randint(0, self.width - 1), random.randint(0, self.height - 1))

    def move(self):
        head_x, head_y = self.snake[0]

        if self.direction == 'right':
            new_head = (head_x + 10, head_y)
        elif self.direction == 'left':
            new_head = (head_x - 10, head_y)
        elif self.direction == 'up':
            new_head = (head_x, head_y - 10)
        elif self.direction == 'down':
            new_head = (head_x, head_y + 10)

        # Check for collision with walls
        if (new_head[0] < 0 or new_head[0] >= self.width or 
            new_head[1] < 0 or new_head[1] >= self.height):
            self.game_over = True
            return

        # Check for collision with self
        if new_head in self.snake:
            self.game_over = True
            return

        # Move snake
        self.snake.insert(0, new_head)

        # Check for food collision
        if new_head == self.food:
            self.score += 1
            self.food = self.generate_food()
        else:
            self.snake.pop()

    def draw(self, surface):
        # Draw snake
        for i, (x, y) in enumerate(self.snake):
            if i == 0:
                # Head
                surface.fill((0, 255, 0), (x, y, 10, 10))
            else:
                # Body
                surface.fill((0, 128, 0), (x, y, 10, 10))

        # Draw food
        surface.fill((255, 0, 0), (self.food[0], self.food[1], 10, 10))

