import random

class Rock:
    def __init__(self, x, y):
        self.x = x
        self.y = y
        self.speed = random.randint(1, 3)
        self.width = 20
        self.height = 20

def create_rock():
    return Rock(random.randint(0, 640), 0)

def update_rocks(rocks, player_x, player_y, score):
    new_rocks = []
    for rock in rocks:
        rock.y += rock.speed
        if rock.y > 480:
            # Rock falls off screen, count as point
            score += 1
            # Remove rock from list
            continue
        new_rocks.append(rock)
    return new_rocks, score

import pygame
import numpy as np

class Background:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.sky = np.full((height, width, 3), (135, 206, 235), dtype=np.uint8)  # Sky blue
        self.road = np.full((height, width, 3), (0, 0, 0), dtype=np.uint8)  # Black road
        self.road_lines = np.full((height, width, 3), (200, 200, 200), dtype=np.uint8)  # Gray road lines

    def draw(self, surface):
        # Draw sky
        surface.blit(self.sky, (0, 0))

        # Draw road
        for y in range(0, self.height):
            if y < 200:
                # Top part of road
                surface.blit(self.road, (0, y))
            else:
                # Bottom part of road
                surface.blit(self.road, (0, y))

        # Draw road lines
        for y in range(0, self.height, 20):
            if y < 200:
                surface.blit(self.road_lines, (0, y))
            else:
                surface.blit(self.road_lines, (0, y))

        # Add simple town elements
        # Add a small building at the edge
        building = np.full((50, 50, 3), (100, 100, 100), dtype=np.uint8)  # Light gray building
        surface.blit(building, (500, 100))

